mapper.select:


  e.del_flag='0' and e.status='0' and p.place_id is not null
  and e.del_flag='0' and e.status=#{status}
  and e.del_flag!='0'
  and e.category=#{category}
  and p.city=#{city}
  and (e.title like concat('%',#{keyword},'%') or e.subtitle like concat('%',#{keyword},'%') or coalesce(p.place_name,e.place_name) like concat('%',#{keyword},'%'))

order by e.display_sort asc,e.published_at desc,e.enjoy_id desc

select ranked.*
from (
  select base.*,
    row_number() over(
      partition by base.category
      order by base.display_sort asc,base.published_at desc,base.enjoy_id desc
    ) category_rank
  from (

    where e.del_flag='0' and e.status='0' and p.place_id is not null
    and p.city=#{city}
  ) base
) ranked
where ranked.category_rank <= #{perCategory}
order by field(ranked.category,'MALL','RESTAURANT','SCENIC','HOTEL'),
         ranked.display_sort asc,ranked.published_at desc,ranked.enjoy_id desc
